/**
 * Generate maskdb firewall config.
 *
 * Data source: https://github.com/e7h4n/maskdb
 *
 * maskdb authenticates with a single Bearer token (a read-only agent token):
 *   - `Authorization: Bearer <token>` → MASKDB_TOKEN (secret)
 */

import { writeOutput } from "./codegen";

const DOCS_URL = "https://github.com/e7h4n/maskdb";
// Format: mk_agent_ prefix + 43 url-safe base64 chars
const PLACEHOLDER_VALUE = "mk_agent_CoffeeSafeLocalCoffeeSafeLocalCoffeeSafeLoca";

function generateTypeScript(): string {
  const lines: string[] = [
    "// Auto-generated from maskdb API docs.",
    `// Source: ${DOCS_URL}`,
    "// Regenerate: cd turbo && pnpm -F @vm0/firewalls-generator generate:maskdb",
    "//",
    "// DO NOT EDIT THIS FILE MANUALLY.",
    "",
    'import type { FirewallConfig } from "../firewall-types";',
    "",
    "export const maskdbFirewall = {",
    '  name: "maskdb",',
    '  description: "maskdb",',
    "  placeholders: {",
    `    MASKDB_TOKEN: "${PLACEHOLDER_VALUE}",`,
    "  },",
    "  apis: [",
    "    {",
    '      base: "https://api.maskdb.ai",',
    "      auth: {",
    "        headers: {",
    '          Authorization: "Bearer ${{ secrets.MASKDB_TOKEN }}",',
    "        },",
    "      },",
    "      permissions: [],",
    "    },",
    "  ],",
    "} as const satisfies FirewallConfig;",
    "",
  ];
  return lines.join("\n");
}

export async function generate(): Promise<void> {
  console.error("Generating maskdb firewall config...");
  const ts = generateTypeScript();
  writeOutput("maskdb", ts, import.meta.dirname);
}
